public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer in = new StreamTokenizer(br);
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;

        int[] diff = new int[m + 2];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            int l = (int) in.nval;
            in.nextToken();
            int r = (int) in.nval;
            diff[l]++;
            diff[r + 1]--;
        }

        int[] cnt = new int[m];
        int cur = 0;
        for (int i = 1; i <= m; i++) {
            cur += diff[i];
            cnt[i - 1] = cur;
        }

        // L[i] = length of longest non-decreasing subsequence ending at i
        int[] L = new int[m];
        int[] tails = new int[m];
        int len = 0;
        for (int i = 0; i < m; i++) {
            int v = cnt[i];
            int pos = upperBound(tails, len, v);
            tails[pos] = v;
            L[i] = pos + 1;
            if (pos == len) len++;
        }

        // R[i] = length of longest non-increasing subsequence starting at i
        int[] R = new int[m];
        int[] tails2 = new int[m];
        int len2 = 0;
        for (int i = m - 1; i >= 0; i--) {
            int v = cnt[i];
            int pos = upperBound(tails2, len2, v);
            tails2[pos] = v;
            R[i] = pos + 1;
            if (pos == len2) len2++;
        }

        int ans = 0;
        for (int i = 0; i < m; i++) {
            int val = L[i] + R[i] - 1;
            if (val > ans) ans = val;
        }

        System.out.println(ans);
    }

    static int upperBound(int[] arr, int len, int v) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] > v) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}
