        System.out.println(total - bad);
    }

    static long countBad(long s, long l) {
        long bad = 0;
        for (long k = 0; k <= l; k++) {
            if (s < 0 && k < -s) {
                bad += (k + 1) * (l - k + 1);
            } else {
                long w = l - s - 2 * k + 1;
                if (w > 0) {
                    bad += (k + 1) * w;
                }
            }
        }
        return bad;
    }
