public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long p = Long.parseLong(st.nextToken());
        long x = Long.parseLong(st.nextToken());

        long d = computeOrder(a, p);
        long invA = modpow(a, p - 2, p);
        long invD = modpow(d % p, p - 2, p); // d < p since d divides p-1

        long M = d * p;
        long count = 0;

        long invAPowR = 1; // inv(a)^r mod p

        for (long r = 0; r < d; r++) {
            long c = (b * invAPowR) % p;
            long diff = ((c - r) % p + p) % p;
            long t = (diff * invD) % p;
            long n0 = r + d * t;

            if (n0 == 0) {
                count += x / M;
            } else {
                if (n0 <= x) {
                    count += (x - n0) / M + 1;
                }
            }

            invAPowR = (invAPowR * invA) % p;
        }

        System.out.println(count);
    }

    static long modpow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        if (base < 0) base += mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long computeOrder(long a, long p) {
        long n = p - 1;
        List<Long> primeFactors = factorize(n);
        long order = n;
        for (long q : primeFactors) {
            while (order % q == 0 && modpow(a, order / q, p) == 1) {
                order /= q;
            }
        }
        return order;
    }

    static List<Long> factorize(long n) {
        List<Long> factors = new ArrayList<>();
        for (long i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                factors.add(i);
                while (n % i == 0) n /= i;
            }
        }
        if (n > 1) factors.add(n);
        return factors;
    }
}
