import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int x = scanner.nextInt();
        int pos = scanner.nextInt();

        int lo = 0, hi = n;
        int less = 0, greater = 0;

        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (mid < pos) {
                // requires a[mid] < x
                less++;
                lo = mid + 1;
            } else if (mid > pos) {
                // requires a[mid] >= x, but since distinct and !=x, a[mid] > x
                greater++;
                hi = mid;
            } else {
                // mid == pos, a[mid] = x, treated as else branch
                hi = mid;
            }
        }

        // Precompute factorials up to n
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        int availLess = x - 1;
        int availGreater = n - x;

        if (less > availLess || greater > availGreater) {
            System.out.println(0);
            return;
        }

        int remaining = n - 1 - less - greater;
        if (remaining < 0) {
            System.out.println(0);
            return;
        }

        long pLess = permutation(availLess, less, fact, invFact);
        long pGreater = permutation(availGreater, greater, fact, invFact);
        long result = pLess * pGreater % MOD;
        result = result * fact[remaining] % MOD;

        System.out.println(result);
    }

    static long permutation(int a, int b, long[] fact, long[] invFact) {
        if (b > a || b < 0) return 0;
        return fact[a] * invFact[a - b] % MOD;
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}
