import java.util.*;

public class Main {
    static long m;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        m = scanner.nextLong();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int n1 = n / 2;
        int n2 = n - n1;

        int[] arr1 = new int[n1];
        int[] arr2 = new int[n2];
        for (int i = 0; i < n1; i++) arr1[i] = a[i];
        for (int i = 0; i < n2; i++) arr2[i] = a[n1 + i];

        long[] sums1 = generateSums(arr1);
        long[] sums2 = generateSums(arr2);

        Arrays.sort(sums2);

        long tMax = sums2[sums2.length - 1];

        long best = 0;

        for (long s : sums1) {
            // candidate 2: use tMax
            long candidate2 = (s + tMax) % m;
            if (candidate2 > best) best = candidate2;

            // candidate 1: find largest t <= (m-1-s) in sums2
            long target = m - 1 - s;
            if (target >= 0) {
                int idx = upperBoundLessEqual(sums2, target);
                if (idx >= 0) {
                    long candidate1 = s + sums2[idx];
                    if (candidate1 > best) best = candidate1;
                }
            }
        }

        System.out.println(best);
    }

    private static long[] generateSums(int[] arr) {
        int k = arr.length;
        int size = 1 << k;
        long[] res = new long[size];
        for (int mask = 0; mask < size; mask++) {
            long sum = 0;
            for (int i = 0; i < k; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[i];
                }
            }
            res[mask] = sum % m;
        }
        return res;
    }

    // Find index of largest element <= target in sorted array, return -1 if none
    private static int upperBoundLessEqual(long[] sortedArr, long target) {
        int lo = 0, hi = sortedArr.length - 1;
        int result = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (sortedArr[mid] <= target) {
                result = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return result;
    }
}
