public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();

        // f[i] = number of valid tilings (permutations) for length i
        long[] f = new long[n + 2];
        f[0] = 1;
        if (n >= 1) f[1] = 1;
        for (int i = 2; i <= n; i++) {
            f[i] = f[i - 1] + f[i - 2];
            // clamp to avoid overflow issues (k is at most 1e18, but n<=50 keeps it safe anyway)
        }

        int[] result = new int[n + 1]; // 1-indexed
        int pos = 1;
        int remaining = n;
        long kk = k;

        while (remaining > 0) {
            if (remaining == 1) {
                result[pos] = pos;
                pos += 1;
                remaining -= 1;
            } else {
                long c1 = f[remaining - 1];
                if (kk <= c1) {
                    // choose type 1 (fixed point)
                    result[pos] = pos;
                    pos += 1;
                    remaining -= 1;
                } else {
                    kk -= c1;
                    // choose type 2 (swap adjacent)
                    result[pos] = pos + 1;
                    result[pos + 1] = pos;
                    pos += 2;
                    remaining -= 2;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(result[i]);
        }
        System.out.println(sb.toString());
    }
}
