        long l = scanner.nextLong();
        long r = scanner.nextLong();

        long maxWeight = Long.MIN_VALUE;

        for (int d = 1; d <= 10; d++) {
            long lower = (d == 1) ? 1L : pow10(d - 1);
            long upper = pow10(d) - 1;

            long lo = Math.max(l, lower);
            long hi = Math.min(r, upper);

            if (lo > hi) continue;

            List<Long> candidates = new ArrayList<>();
            candidates.add(lo);
            candidates.add(hi);
            long vertex = upper / 2;
            candidates.add(vertex);
            candidates.add(vertex + 1);

            for (long n : candidates) {
                if (n >= lo && n <= hi) {
                    long weight = n * (upper - n);
                    if (weight > maxWeight) {
                        maxWeight = weight;
                    }
                }
            }
        }

        System.out.println(maxWeight);
    }

    private static long pow10(int exp) {
        long result = 1;
        for (int i = 0; i < exp; i++) {
            result *= 10;
        }
        return result;
    }
}
