public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long l = scanner.nextLong();
        long r = scanner.nextLong();

        List<Long> powX = getPowers(x, r);
        List<Long> powY = getPowers(y, r);

        TreeSet<Long> unlucky = new TreeSet<>();
        for (long px : powX) {
            for (long py : powY) {
                // sum could be up to 2e18, fits in long since long max ~9.22e18
                long sum = px + py;
                if (sum >= l && sum <= r) {
                    unlucky.add(sum);
                }
            }
        }

        long maxGap = 0;
        long prev = l - 1; // boundary before l

        for (long val : unlucky) {
            long gap = val - prev - 1;
            if (gap > maxGap) maxGap = gap;
            prev = val;
        }
        // after last unlucky year to r
        long gap = r - prev;
        if (gap > maxGap) maxGap = gap;

        System.out.println(maxGap);
    }

    private static List<Long> getPowers(long base, long limit) {
        List<Long> result = new ArrayList<>();
        long val = 1;
        result.add(val);
        while (true) {
            // check overflow before multiplying
            if (val > limit / base) {
                break;
            }
            long next = val * base;
            if (next > limit) {
                break;
            }
            val = next;
            result.add(val);
        }
        return result;
    }
}
