        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] ea = new int[m];
        int[] eb = new int[m];
        for (int i = 0; i < m; i++) {
            ea[i] = scanner.nextInt() - 1;
            eb[i] = scanner.nextInt() - 1;
        }

        int[] labels = new int[n];
        int best = solve(0, n, labels, ea, eb, m);
        System.out.println(best);
    }

    private static int solve(int idx, int n, int[] labels, int[] ea, int[] eb, int m) {
        if (idx == n) {
            boolean[][] used = new boolean[7][7];
            int count = 0;
            for (int i = 0; i < m; i++) {
                int a = labels[ea[i]];
                int b = labels[eb[i]];
                int lo = Math.min(a, b);
                int hi = Math.max(a, b);
                if (!used[lo][hi]) {
                    used[lo][hi] = true;
                    count++;
                }
            }
            return count;
        }
        int best = 0;
        for (int v = 1; v <= 6; v++) {
            labels[idx] = v;
            int res = solve(idx + 1, n, labels, ea, eb, m);
            if (res > best) best = res;
        }
        return best;
    }
