import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        Map<Long, Integer> factors = factorize(n);

        long result = 1L;

        for (Map.Entry<Long, Integer> entry : factors.entrySet()) {
            long p = entry.getKey();
            int e = entry.getValue();

            // dp[a] = probability (mod) of being at exponent a
            long[] dp = new long[e + 1];
            dp[e] = 1L;

            // precompute inverse of denominators 1..e+1
            long[] invDenom = new long[e + 2];
            for (int d = 1; d <= e + 1; d++) {
                invDenom[d] = modpow(d, MOD - 2, MOD);
            }

            long[] arr = new long[e + 1];
            long[] suf = new long[e + 1];

            for (int step = 0; step < k; step++) {
                for (int a = 0; a <= e; a++) {
                    long denomInv = invDenom[a + 1];
                    arr[a] = (dp[a] * denomInv) % MOD;
                }
                suf[e] = arr[e];
                for (int a = e - 1; a >= 0; a--) {
                    suf[a] = (suf[a + 1] + arr[a]) % MOD;
                }
                // new dp[b] = suf[b]
                for (int b = 0; b <= e; b++) {
                    dp[b] = suf[b];
                }
            }

            // compute sum_{s=0}^{e} dp[s] * p^s mod MOD
            long sum = 0L;
            long pPow = 1L % MOD;
            long pMod = p % MOD;
            for (int s = 0; s <= e; s++) {
                sum = (sum + dp[s] * pPow) % MOD;
                pPow = (pPow * pMod) % MOD;
            }

            result = (result * sum) % MOD;
        }

        System.out.println(result % MOD);
    }

    static Map<Long, Integer> factorize(long n) {
        Map<Long, Integer> factors = new LinkedHashMap<>();
        long num = n;
        for (long p = 2; p * p <= num; p++) {
            if (num % p == 0) {
                int cnt = 0;
                while (num % p == 0) {
                    num /= p;
                    cnt++;
                }
                factors.put(p, cnt);
            }
        }
        if (num > 1) {
            factors.put(num, factors.getOrDefault(num, 0) + 1);
        }
        return factors;
    }

    static long modpow(long base, long exp, long mod) {
        base %= mod;
        if (base < 0) base += mod;
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
