public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int t = scanner.nextInt();

        int PZ = t + 1;      // peaks can be 0..t
        int VZ = t;          // valleys can be 0..t-1, if t-1 could be 0 => size at least 1
        if (VZ < 1) VZ = 1;

        // dp[pos][y][dirIn][peaks][valleys]
        // dirIn: 0 = none (only at pos=1), 1 = up (last step was upward), 2 = down (last step was downward)
        long[][][][][] dp = new long[n + 1][5][3][PZ][VZ];

        // initialize pos = 1
        for (int y = 1; y <= 4; y++) {
            dp[1][y][0][0][0] = 1;
        }

        for (int pos = 1; pos < n; pos++) {
            for (int y = 1; y <= 4; y++) {
                for (int dirIn = 0; dirIn < 3; dirIn++) {
                    for (int p = 0; p < PZ; p++) {
                        for (int v = 0; v < VZ; v++) {
                            long cur = dp[pos][y][dirIn][p][v];
                            if (cur == 0) continue;

                            for (int y2 = 1; y2 <= 4; y2++) {
                                if (y2 == y) continue; // no horizontal segment
                                int dirOut = (y2 > y) ? 1 : 2; // 1 = up, 2 = down

                                int newP = p;
                                int newV = v;
                                boolean valid = true;

                                if (dirIn != 0) {
                                    // we have a previous direction, check for peak/valley at 'pos'
                                    if (dirIn == 1 && dirOut == 2) {
                                        // up then down => peak
                                        newP = p + 1;
                                        if (newP >= PZ) valid = false;
                                    } else if (dirIn == 2 && dirOut == 1) {
                                        // down then up => valley
                                        newV = v + 1;
                                        if (newV >= VZ) valid = false;
                                    }
                                    // else same direction continues, no change
                                }

                                if (!valid) continue;

                                dp[pos + 1][y2][dirOut][newP][newV] += cur;
                            }
                        }
                    }
                }
            }
        }

        long answer = 0;
        int targetPeaks = t;
        int targetValleys = t - 1;
        if (targetValleys < 0) targetValleys = 0; // shouldn't happen since t>=1

        for (int y = 1; y <= 4; y++) {
            for (int dirIn = 1; dirIn < 3; dirIn++) { // dirIn can't be 0 at pos=n since n>=3 (at least one step happened)
                if (targetPeaks < PZ && targetValleys < VZ) {
                    answer += dp[n][y][dirIn][targetPeaks][targetValleys];
                }
            }
        }

        System.out.println(answer);
    }
}
