import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long k = scanner.nextLong();

        // Determine m: smallest m<=n such that m! >= k
        long fact = 1;
        int m = 0;
        while (fact < k && m < n) {
            m++;
            fact *= m;
            if (fact > (long) 4e18) { // avoid overflow, but k<=1e9 so this won't be reached normally
                break;
            }
        }

        if (fact < k) {
            System.out.println(-1);
            return;
        }

        // partA: count lucky numbers <= n-m (since positions there have ai = i)
        long limitA = n - m;
        long partA = countLuckyUpTo(limitA);

        // Now compute permutation tail of size m using factorial number system
        long count = partA;

        if (m > 0) {
            // available values: n-m+1 ... n
            List<Long> available = new ArrayList<>();
            for (long v = n - m + 1; v <= n; v++) {
                available.add(v);
            }

            // precompute factorials up to m
            long[] factArr = new long[m + 1];
            factArr[0] = 1;
            for (int i = 1; i <= m; i++) {
                factArr[i] = factArr[i - 1] * i;
            }

            long idx = k - 1; // 0-indexed

            for (int i = 0; i < m; i++) {
                int remaining = m - 1 - i; // remaining elements after this pick
                long f = factArr[remaining];
                int pos = (int) (idx / f);
                idx = idx % f;

                long value = available.get(pos);
                available.remove(pos);

                long position = n - m + 1 + i;

                if (isLucky(position) && isLucky(value)) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }

    private static boolean isLucky(long x) {
        if (x <= 0) return false;
        while (x > 0) {
            long d = x % 10;
            if (d != 4 && d != 7) return false;
            x /= 10;
        }
        return true;
    }

    private static long countLuckyUpTo(long limit) {
        if (limit <= 0) return 0;
        List<Long> luckyNumbers = new ArrayList<>();
        generateLucky(0, luckyNumbers, limit);
        return luckyNumbers.size();
    }

    private static void generateLucky(long current, List<Long> list, long limit) {
        if (current > limit && current != 0) {
            return;
        }
        if (current != 0) {
            list.add(current);
        }
        if (current > limit) {
            return;
        }
        long next4 = current * 10 + 4;
        long next7 = current * 10 + 7;
        if (next4 <= limit || current == 0) {
            if (next4 <= 2000000000L) { // safety bound
                generateLucky(next4, list, limit);
            }
        }
        if (next7 <= limit || current == 0) {
            if (next7 <= 2000000000L) {
                generateLucky(next7, list, limit);
            }
        }
    }
}
